export interface BodyOptions {
    id: string;
    type: 'Rectangle' | 'Ellipse' | 'Triangle' | 'Star' | 'Polygon';
    x: number;
    y: number;
    width: number;
    height: number;
    /** Rectangle corner radius: the collider gets the same rounded corners (a pill rolls like one). */
    cornerRadius?: number;
    rotation?: number;
    isStatic: boolean;
    mass?: number;
    friction?: number;
    restitution?: number;
    frictionAir?: number;
    density?: number;
    isSensor?: boolean;
    /** Keep the body upright (no spinning). */
    lockRotation?: boolean;
    /** Multiplier on scene gravity for this body (negative floats up, like a balloon). */
    gravityScale?: number;
    /** Allow movement along one axis only: 'x' slides horizontally, 'y' slides vertically. */
    lockAxis?: 'x' | 'y';
}
export interface JointOptions {
    id: string;
    type: 'Distance' | 'Revolute' | 'Prismatic' | 'Rope' | 'Fixed';
    bodyA: string;
    bodyB: string;
    anchorA: {
        x: number;
        y: number;
    };
    anchorB: {
        x: number;
        y: number;
    };
    length?: number;
    stiffness?: number;
    damping?: number;
    /** Prismatic: slide axis in bodyA space (default x) and travel limits [min, max]. */
    axis?: {
        x: number;
        y: number;
    };
    /** Prismatic: [min, max] px along the axis. Revolute: [min, max] radians. */
    limits?: [number, number];
    /** Let the two joined bodies collide with each other (default false). */
    collide?: boolean;
}
export interface PhysicsEngine {
    init(gravity: {
        x: number;
        y: number;
    }): Promise<void>;
    destroy(): void;
    setGravity(gravity: {
        x: number;
        y: number;
    }): void;
    setContainment?(rect: {
        minX: number;
        minY: number;
        maxX: number;
        maxY: number;
    } | null): void;
    createBody(options: BodyOptions): void;
    removeBody(id: string): void;
    createJoint(options: JointOptions): void;
    removeJoint(id: string): void;
    step(dt: number): void;
    getPosition(id: string): {
        x: number;
        y: number;
    } | null;
    getRotation(id: string): number | null;
    getVelocity(id: string): {
        x: number;
        y: number;
    } | null;
    setPosition(id: string, x: number, y: number): void;
    setRotation(id: string, angle: number): void;
    setVelocity(id: string, vx: number, vy: number): void;
    setAngularVelocity(id: string, omega: number): void;
    applyForce(id: string, fx: number, fy: number): void;
    applyImpulse(id: string, ix: number, iy: number): void;
    setCollisionCallback?(cb: (a: string, b: string, started: boolean) => void): void;
    grab?(id: string, x: number, y: number): void;
    setGrabTarget?(x: number, y: number): void;
    release?(): void;
}
